query ClassicRoundRecord($number: Int!, $main: ID!, $baseline: ID!) {
  rounds(tournament: 8, number: $number) { number tournament target openTime closeStakingTime closeTime scoreTime resolveTime }
  JACKIE_GENG: v2RoundModelPerformances(modelId: $main, tournament: 8, submittedOnly: true) { roundNumber submissionId tickersSubmittedCount tickersAcceptedCount }
  JACKIE_GENG_BASELINE: v2RoundModelPerformances(modelId: $baseline, tournament: 8, submittedOnly: true) { roundNumber submissionId tickersSubmittedCount tickersAcceptedCount }
}
